rule.example:
fun collectBad(completionService: CompletionService<List<Any>>): Future<List<Any>> {
    return completionService.take() // bad
}

fun collectGood(completionService: CompletionService<List<Any>>): Future<List<Any>>? {
    return completionService.poll(3L, TimeUnit.SECONDS) // good
}

fun bad(complFuture: CompletableFuture<String>): String {
    return complFuture.get() // bad
}

fun good(complFuture: CompletableFuture<String>): String {
    return complFuture.get(10, TimeUnit.SECONDS) // good
}

property.value:
(: future.join() without any timeout method anywhere in the same function body :)
//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('java.util.concurrent.Future#join()')
    and ./PostfixUnarySuffix/NavigationSuffix[@Identifier='join']
    and not(
        ancestor::FunctionBody//PostfixUnaryExpression[
            pmd-kotlin:matchesSig('java.util.concurrent.Future#get(_,java.util.concurrent.TimeUnit)')
            or pmd-kotlin:matchesSig('java.util.concurrent.CompletableFuture#orTimeout(_,java.util.concurrent.TimeUnit)')
            or pmd-kotlin:matchesSig('java.util.concurrent.CompletableFuture#completeOnTimeout(_,_,java.util.concurrent.TimeUnit)')
        ]
    )
]

rule.example:
fun getOrdersBad(futures: List<CompletableFuture<Order>>): List<Order> {
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // bad, no timeout provided
}

fun getOrdersGood(futures: List<CompletableFuture<Order>>): List<Order> {
    val allResult = CompletableFuture.allOf(*futures.toTypedArray())
    try {
        allResult.get(5L, TimeUnit.SECONDS) // good - timeout
    } catch (e: Exception) { }
    return futures
        .filter { it.isDone && !it.isCompletedExceptionally }
        .map { it.join() } // good - timeout provided above
}

@Service
class MyService {
    @Value("\${batchService.http.url}")
    var url: String = ""

    @GuardedBy("lock")
    var guardedUrl: String = ""

    fun setUrlBad(url: String) {
        this.url = url // bad: unguarded accessor method
    }

    @Synchronized
    fun setUrlGood(url: String) {
        this.url = url // good: synchronized accessor method
    }
}

@Controller
class RootController {

    var baskets: List<Any> = listOf()          // bad, not private
    protected var baskets2: List<Any> = listOf() // bad, not private
    val baskets3: List<Any> = listOf()          // good, val (final)
    private var baskets4: List<Any> = listOf()  // good, private

    @Autowired
    lateinit var baskets5: List<Any>           // allowed, injected
}

class Foo {
    private val asyncPool = Executors.newFixedThreadPool(8)

    fun bad(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync { isAccountBlocked(it) } // bad, uses common pool
        }
    }

    fun good(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync({ isAccountBlocked(it) }, asyncPool) // good
        }
    }
}

class Bad {
    var date: String = ""

    fun setDate(d: String) {
        date = d // bad - synchronized used in class
    }

    @Synchronized
    fun getDate(): String = date
}

@NotThreadSafe
class Good {
    var date: String = ""

    fun setDate(d: String) {
        date = d // good - @NotThreadSafe
    }
}

@Component
class Bad {
    var url: String = ""  // bad, unguarded var field

    fun setUrlBad(url: String) {
        this.url = url
    }
}

@Component
class BadMutableTypes {
    val date: Date = Date()                           // bad, Date is mutable
    @Volatile var strBuilder: StringBuilder = StringBuilder() // bad, mutable type
    val map: HashMap<String, String> = HashMap()      // bad, mutable collection

    @GuardedBy("this")
    val guardedMap: HashMap<String, String> = HashMap() // good, guarded
}

class Bad {
    var date: String = ""  // bad, unguarded var field in class using synchronized

    fun setDate(d: String) {
        date = d
    }

    @Synchronized
    fun getDate(): String = date
}

class Good {
    @net.jcip.annotations.GuardedBy("this")
    var date: String = ""  // good, guarded

    @Synchronized
    fun getDate(): String = date
}

@org.springframework.stereotype.Component
class Bad : SomeParent() {
    fun mutateDateBad() {
        date.setTime(100) // bad - unguarded mutator on inherited field
    }
    fun mutateMapBad(key: String, value: String) {
        map.put(key, value) // bad - unguarded mutator on inherited field
    }
}

@org.springframework.stereotype.Component
class Good : SomeParent() {
    @Synchronized
    fun mutateMapGood(key: String, value: String) {
        map.put(key, value) // good - synchronized
    }
}

property.value:
(: Kotlin: NotProperlySynchronizingOnThisWhileUsingGuardedBy :)
(: Detect access to @GuardedBy("this") fields outside @Synchronized or synchronized(this) :)

(: let $guardedByThisFields be the set of field names annotated with @GuardedBy("this") :)
(: Match writes (Assignment) and reads (PrimaryExpression) to those fields :)

(: Writes: assignments to @GuardedBy("this") fields :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Synchronized')
  )
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//Assignment[
  (: assignment target matches a @GuardedBy("this") field :)
  (DirectlyAssignableExpression|AssignableExpression)//T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[@Text='this']
    ]/VariableDeclaration/@Identifier
  ]
  (: not inside synchronized(this) block :)
  and not(ancestor::LambdaLiteral[
    ancestor::PostfixUnaryExpression[
      PrimaryExpression//T-Identifier[@Text='synchronized']
      and .//CallSuffix/ValueArguments//T-Identifier[@Text='this']
    ]
  ])
]
|
(: Reads: PrimaryExpression references to @GuardedBy("this") fields :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Synchronized')
  )
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//PrimaryExpression[
  (: must be inside function body :)
  ancestor::FunctionBody
  and SimpleIdentifier/T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[@Text='this']
    ]/VariableDeclaration/@Identifier
  ]
  (: not a function call (function name followed by CallSuffix) :)
  and not(parent::PostfixUnaryExpression/PostfixUnarySuffix/CallSuffix)
  (: not inside synchronized(this) block :)
  and not(ancestor::LambdaLiteral[
    ancestor::PostfixUnaryExpression[
      PrimaryExpression//T-Identifier[@Text='synchronized']
      and .//CallSuffix/ValueArguments//T-Identifier[@Text='this']
    ]
  ])
]

rule.example:
class Bad {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String { return txt } // bad - not synchronized
    fun setText(t: String) { txt = t }   // bad - not synchronized
}

class Good {
    @GuardedBy("this")
    var txt: String = ""

    @Synchronized
    fun getText(): String { return txt } // good
    @Synchronized
    fun setText(t: String) { txt = t }   // good
}

property.value:
(: Kotlin: NotProperlySynchronizingOnFieldWhileUsingGuardedBy :)
(: Two parts: :)
(: 1. @GuardedBy value IS a field name -> check synchronized(field) :)
(: 2. @GuardedBy value is NOT "this" and NOT a field -> always flag :)

(: Part 1: Writes to @GuardedBy(fieldLock) fields not inside synchronized(fieldLock) :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//Assignment[
  (: assignment target matches a @GuardedBy(fieldName) field where fieldName IS a property :)
  (DirectlyAssignableExpression|AssignableExpression)//T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[
        not(@Text = 'this')
        and @Text = ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]/VariableDeclaration/@Identifier
      ]
    ]/VariableDeclaration/@Identifier
  ]
  (: not inside synchronized(lockField) where lockField matches the @GuardedBy value :)
  and not(
    ancestor::LambdaLiteral[
      ancestor::PostfixUnaryExpression[
        PrimaryExpression//T-Identifier[@Text='synchronized']
        and .//CallSuffix/ValueArguments//T-Identifier/@Text =
          ancestor::ClassBody[1]//PropertyDeclaration[
            not(ancestor::FunctionBody)
            and .//Annotation[.//T-Identifier[@Text='GuardedBy']]
          ]//T-LineStrText/@Text
      ]
    ]
  )
]
|
(: Part 1b: Reads of @GuardedBy(fieldLock) fields not inside synchronized(fieldLock) :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//PrimaryExpression[
  ancestor::FunctionBody
  and SimpleIdentifier/T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[
        not(@Text = 'this')
        and @Text = ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]/VariableDeclaration/@Identifier
      ]
    ]/VariableDeclaration/@Identifier
  ]
  and not(parent::PostfixUnaryExpression/PostfixUnarySuffix/CallSuffix)
  and not(
    ancestor::LambdaLiteral[
      ancestor::PostfixUnaryExpression[
        PrimaryExpression//T-Identifier[@Text='synchronized']
        and .//CallSuffix/ValueArguments//T-Identifier/@Text =
          ancestor::ClassBody[1]//PropertyDeclaration[
            not(ancestor::FunctionBody)
            and .//Annotation[.//T-Identifier[@Text='GuardedBy']]
          ]//T-LineStrText/@Text
      ]
    ]
  )
]
|
(: Part 2: @GuardedBy value is NOT "this" and NOT a field name -> always flag writes :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//Assignment[
  (DirectlyAssignableExpression|AssignableExpression)//T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[
        not(@Text = 'this')
        and not(@Text = ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]/VariableDeclaration/@Identifier)
      ]
    ]/VariableDeclaration/@Identifier
  ]
]
|
(: Part 2b: same for reads :)
//FunctionDeclaration[
  ancestor::ClassBody
  and not(
    pmd-kotlin:hasAnnotation('Autowired')
    or pmd-kotlin:hasAnnotation('PostConstruct')
    or pmd-kotlin:hasAnnotation('org.springframework.batch.core.annotation.BeforeStep')
    or pmd-kotlin:hasAnnotation('Value')
    or pmd-kotlin:hasAnnotation('Inject')
  )
]//PrimaryExpression[
  ancestor::FunctionBody
  and SimpleIdentifier/T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[
        not(@Text = 'this')
        and not(@Text = ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]/VariableDeclaration/@Identifier)
      ]
    ]/VariableDeclaration/@Identifier
  ]
  and not(parent::PostfixUnaryExpression/PostfixUnarySuffix/CallSuffix)
]

rule.example:
class Bad {
    private val lock = Any()
    @GuardedBy("lock")
    var txt: String = ""

    fun getText(): String { return txt } // bad
    fun setText(t: String) { txt = t }   // bad, not synchronized on lock
}

class Good {
    private val lock = Any()
    @GuardedBy("lock")
    var txt: String = ""

    fun getText(): String {
        return synchronized(lock) { txt } // good
    }
    fun setText(t: String) {
        synchronized(lock) { txt = t }    // good
    }
}

property.value:
(: Kotlin: WrongUseOfGuardedBy :)

(: Check 1: @GuardedBy argument is not a String literal :)
//PropertyDeclaration[not(ancestor::FunctionBody)]
  //Annotation[.//T-Identifier[@Text='GuardedBy']]
    [.//ValueArguments/ValueArgument[not(.//LineStringLiteral)]]

|
(: Check 2: @GuardedBy value refers to non-existent field, not "this" :)
//PropertyDeclaration[not(ancestor::FunctionBody)]
  //Annotation[.//T-Identifier[@Text='GuardedBy']]
    //T-LineStrText[
      not(@Text = 'this')
      and not(@Text = ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]/VariableDeclaration/@Identifier)
    ]

|
(: Check 3: @GuardedBy("this") but no @Synchronized method and no synchronized(this) call in class :)
//PropertyDeclaration[not(ancestor::FunctionBody)]
  //Annotation[.//T-Identifier[@Text='GuardedBy']]
    //T-LineStrText[@Text = 'this'
      and not(ancestor::ClassBody[1]//FunctionDeclaration[
        pmd-kotlin:hasAnnotation('Synchronized')
      ])
      and not(ancestor::ClassBody[1]//PostfixUnaryExpression[
        PrimaryExpression//T-Identifier[@Text='synchronized']
        and .//CallSuffix/ValueArguments//T-Identifier[@Text='this']
      ])
    ]

|
(: Check 4: Lock field used in @GuardedBy is not private val :)
//PropertyDeclaration[
  not(ancestor::FunctionBody)
  (: this property is referenced by a @GuardedBy annotation :)
  and VariableDeclaration/@Identifier =
    ancestor::ClassBody[1]//PropertyDeclaration[not(ancestor::FunctionBody)]
      //Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText/@Text
  (: but it is not private val :)
  and (T-VAR or not(pmd-kotlin:modifiers() = 'private'))
]

rule.example:
class WrongUseOfGuardedBy {
    companion object { const val FIELD = "field" }
    @GuardedBy(FIELD) // bad, not a String literal
    var cachedData: MutableMap<String, String> = HashMap()
}

class RightUseOfGuardedBy {
    private val lock = Any()

    @GuardedBy("lock") // good, String literal referring to existing private val lock
    var cachedData: MutableMap<String, String> = HashMap()

    fun getValue(key: String): String? {
        return synchronized(lock) { cachedData[key] }
    }
}
